// Look up a domain's registration (registrar, expiry, status) via RDAP, the
// successor to WHOIS. rdap.org redirects to the right registry for each TLD.
const raw = String($input.first().json.body?.domain ?? '').trim().toLowerCase();
const host = raw.replace(/^https?:[/][/]/, '').split('/')[0].split(':')[0].replace(/[.]$/, '');
// RDAP needs the registrable domain, not a subdomain.
const parts = host.split('.');
const TWO_LEVEL_SUFFIXES = ['co.uk', 'org.uk', 'com.pa', 'com.au', 'co.nz'];
const domain = TWO_LEVEL_SUFFIXES.includes(parts.slice(-2).join('.')) ? parts.slice(-3).join('.') : parts.slice(-2).join('.');

let res;
try {
  res = await this.helpers.httpRequest({ method: 'GET', url: 'https://rdap.org/domain/' + domain, headers: { Accept: 'application/rdap+json' }, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000, json: true });
} catch (e) {
  return [{ json: { domain, lookup_ok: false, error: e.message } }];
}
if (res.statusCode === 404) {
  return [{ json: { domain, lookup_ok: true, registered: false, problems: ['not_registered'], warnings: [], source: 'rdap' } }];
}
if (res.statusCode !== 200) {
  return [{ json: { domain, lookup_ok: false, error: 'RDAP returned HTTP ' + res.statusCode } }];
}

const j = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
const eventDate = (action) => (j.events || []).find(e => e.eventAction === action)?.eventDate ?? null;
const expires = eventDate('expiration');
const registrarEntity = (j.entities || []).find(e => (e.roles || []).includes('registrar'));
const registrar = registrarEntity?.vcardArray?.[1]?.find(f => f[0] === 'fn')?.[3] ?? null;
const status = (j.status || []).map(s => s.toLowerCase());
const days = expires ? Math.floor((new Date(expires) - new Date()) / 86400000) : null;

// problems = the domain is at risk of going offline; warnings = worth attention.
const problems = [];
if (days !== null && days < 0) problems.push('expired');
else if (days !== null && days <= 30) problems.push('expiring_within_30_days');
if (status.some(s => s.includes('hold'))) problems.push('on_hold');
if (status.some(s => s.includes('redemption'))) problems.push('redemption_period');
if (status.some(s => s.includes('pending delete'))) problems.push('pending_delete');
const warnings = [];
if (days !== null && days > 30 && days <= 60) warnings.push('expiring_within_60_days');
if (!status.some(s => s.includes('transfer prohibited'))) warnings.push('no_transfer_lock');

return [{ json: {
  domain,
  lookup_ok: true,
  registered: true,
  expires,
  days_until_expiry: days,
  registered_on: eventDate('registration'),
  last_changed: eventDate('last changed'),
  registrar,
  status,
  nameservers: (j.nameservers || []).map(n => (n.ldhName || '').toLowerCase()),
  problems,
  warnings,
  source: 'rdap',
} }];
